namespace Handyman.Api.Domain.Entities;

// DomainException lives in Handyman.Api.Domain (parent namespace, resolved automatically).

public enum JobStatus { Open, Assigned, Done, Closed, Cancelled }

public enum BidStatus { Active, Accepted, Rejected, Withdrawn }

public class Job
{
    public Guid Id { get; set; }
    /// <summary>Human-friendly number, generated by the database.</summary>
    public int Number { get; set; }
    public Guid ClientId { get; set; }
    public int TradeId { get; set; }
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int AreaId { get; set; }
    public string Street { get; set; } = "";
    public string HouseNumber { get; set; } = "";
    public string? Entrance { get; set; }
    public string? Floor { get; set; }
    public string? Apartment { get; set; }
    public string? AddressNote { get; set; }
    public int? StoreId { get; set; }
    public JobStatus Status { get; private set; } = JobStatus.Open;
    /// <summary>Plain column, no foreign key: jobs and bids point at each other.</summary>
    public Guid? AcceptedBidId { get; private set; }
    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;
    public DateTimeOffset? FinishedAt { get; private set; }
    public DateTimeOffset? ClosedAt { get; private set; }

    /// <summary>
    /// Open -> Assigned. <paramref name="jobBids"/> must be all bids of this job, including the hired one.
    /// The hired bid becomes accepted, active bids become rejected, withdrawn bids stay withdrawn.
    /// </summary>
    public void Hire(Bid bid, IEnumerable<Bid> jobBids)
    {
        if (Status != JobStatus.Open)
            throw new DomainException("job_not_open", $"Job is {Status}; only an Open job can be hired.");
        if (bid.JobId != Id)
            throw new DomainException("bid_job_mismatch", "The bid belongs to another job.");
        if (bid.Status != BidStatus.Active)
            throw new DomainException("bid_not_active", $"Bid is {bid.Status}; only an active bid can be hired.");

        var others = jobBids.Where(b => b.Id != bid.Id).ToList();
        if (others.Any(b => b.JobId != Id))
            throw new DomainException("bid_job_mismatch", "A bid in the list belongs to another job.");

        bid.Status = BidStatus.Accepted;
        foreach (var other in others.Where(b => b.Status == BidStatus.Active))
            other.Status = BidStatus.Rejected;
        AcceptedBidId = bid.Id;
        Status = JobStatus.Assigned;
    }

    /// <summary>Assigned -> Done.</summary>
    public void Finish(DateTimeOffset now)
    {
        if (Status != JobStatus.Assigned)
            throw new DomainException("job_not_assigned", $"Job is {Status}; only an Assigned job can be finished.");
        Status = JobStatus.Done;
        FinishedAt = now.ToUniversalTime();
    }

    /// <summary>
    /// Records a rating on a Done job and returns it; the caller adds it to the context.
    /// The job does not know the hired worker, so the handler must load and pass:
    /// <paramref name="acceptedBid"/> (the bid with Id == AcceptedBidId; its WorkerId is the hired worker) and
    /// <paramref name="jobRatings"/> (all ratings already stored for this job).
    /// Only the client or the hired worker may rate, once each; the ratee is the other party.
    /// When both ratings exist the job becomes Closed with ClosedAt in UTC. On any refusal nothing changes.
    /// </summary>
    public Rating AddRating(Guid raterId, int stars, string? comment, DateTimeOffset now,
        Bid acceptedBid, IEnumerable<Rating> jobRatings)
    {
        if (Status != JobStatus.Done)
            throw new DomainException("job_not_done", $"Job is {Status}; only a Done job can be rated.");
        if (acceptedBid.JobId != Id || acceptedBid.Id != AcceptedBidId)
            throw new DomainException("bid_not_accepted", "The bid is not the accepted bid of this job.");

        var workerId = acceptedBid.WorkerId;
        Guid rateeId;
        if (raterId == ClientId) rateeId = workerId;
        else if (raterId == workerId) rateeId = ClientId;
        else throw new DomainException("not_allowed", "Only the job's client or its hired worker can rate it.");

        if (stars is < 1 or > 5)
            throw new DomainException("invalid_stars", "Stars must be between 1 and 5.");

        var ratings = jobRatings.ToList();
        if (ratings.Any(r => r.JobId != Id))
            throw new DomainException("rating_job_mismatch", "A rating in the list belongs to another job.");
        if (ratings.Any(r => r.RaterId == raterId))
            throw new DomainException("already_rated", "This user has already rated the job.");

        var rating = new Rating
        {
            Id = Guid.NewGuid(),
            JobId = Id,
            RaterId = raterId,
            RateeId = rateeId,
            Stars = stars,
            Comment = comment,
            CreatedAt = now.ToUniversalTime(),
        };

        if (ratings.Any(r => r.RaterId == rateeId))
        {
            Status = JobStatus.Closed;
            ClosedAt = now.ToUniversalTime();
        }
        return rating;
    }

    /// <summary>Open or Assigned -> Cancelled. Bids keep their status.</summary>
    public void Cancel()
    {
        if (Status is not (JobStatus.Open or JobStatus.Assigned))
            throw new DomainException("job_not_cancellable", $"Job is {Status}; only an Open or Assigned job can be cancelled.");
        Status = JobStatus.Cancelled;
    }
}

public class JobPhoto
{
    public Guid Id { get; set; }
    public Guid JobId { get; set; }
    public string StoragePath { get; set; } = "";
}

public class Bid
{
    public Guid Id { get; set; }
    public Guid JobId { get; set; }
    public Guid WorkerId { get; set; }
    public DateTimeOffset ArrivalWindowStart { get; set; }
    public DateTimeOffset ArrivalWindowEnd { get; set; }
    /// <summary>Whole RSD.</summary>
    public int DiagnosticFee { get; set; }
    /// <summary>Whole RSD.</summary>
    public int HourlyRate { get; set; }
    public string? Note { get; set; }
    public BidStatus Status { get; internal set; } = BidStatus.Active;
    public DateTimeOffset CreatedAt { get; set; }
}

public class Rating
{
    public Guid Id { get; set; }
    public Guid JobId { get; set; }
    public Guid RaterId { get; set; }
    public Guid RateeId { get; set; }
    public int Stars { get; set; }
    public string? Comment { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
}
